boolean-fill.source:
function fillValues(array: List<Boolean>, value: Boolean) {
 let i = 0; while i<array.length { array[i] = value; i = i+1 }
}
let sizes = 1; let cases = 0; let verified = 0
while sizes<1024 {
 let choice = 0
 while choice<2 {
  let values: List<Boolean> = []; let i = 0
  while i<sizes { values.add(false); i = i+1 }
  let expected = choice==1
  fillValues(values,expected)
  if values.length!=sizes { fail("fill size") }
  i = 0
  while i<sizes {
   if values[i]!=expected { print(sizes); print(choice); print(i); fail("Boolean fill") }
   verified = verified+1; i = i+1
  }
  cases = cases+1; choice = choice+1
 }
 sizes = sizes+1
}
print(cases); print(verified)

