function fillValues(array: List<Integer>, value: Integer) {
 let i = 0; while i<array.length { array[i] = value; i = i+1 }
}
function workload() {
 let sizes = 1; let cases = 0; let verified = 0
 while sizes<1024 {
  let value = -128
  while value<128 {
   let values: List<Integer> = []; let i = 0
   while i<sizes { values.add(0); i = i+1 }
   fillValues(values,value)
   if values.length!=sizes { fail("fill size") }
   i = 0
   while i<sizes {
    if values[i]!=value { print(sizes); print(value); print(i); fail("signed byte fill") }
    verified = verified+1; i = i+1
   }
   cases = cases+1; value = value+1
  }
  sizes = sizes+1
 }
 print(cases); print(verified)
}
workload()
